package com.cinenest.access.internal;
import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import java.util.*;import static org.assertj.core.api.Assertions.*;
class AccessPolicyTest {
 MockEnvironment env(){var e=new MockEnvironment().withProperty("cinenest.access.enabled","true").withProperty("cinenest.access.mode","SYNTHETIC_BANK_ONLY").withProperty("cinenest.access.key-version","test-v1").withProperty("cinenest.access.keys.test-v1",Base64.getEncoder().encodeToString(new byte[32]));for(String k:List.of("attempt-limit","retry-limit","rate-count","rate-seconds","disclosure-limit","retention-seconds"))e.setProperty("cinenest.access."+k,"10");return e;}
 @Test void secure32ByteTokensAreUniqueAndEncryptedWithAuthenticatedBinding(){var p=new AccessPolicy(env());p.configured();var seen=new HashSet<String>();for(int n=0;n<1000;n++){String t=p.token();assertThat(Base64.getUrlDecoder().decode(t)).hasSize(32);assertThat(seen.add(t)).isTrue();UUID id=UUID.randomUUID();var enc=p.protect(t,p.version(),id);assertThat(new String(enc,java.nio.charset.StandardCharsets.UTF_8)).doesNotContain(t);assertThat(p.reveal(enc,p.version(),id)).isEqualTo(t);assertThatThrownBy(()->p.reveal(enc,p.version(),UUID.randomUUID())).isInstanceOf(AccessFailure.class);}}
 @Test void explicitPositiveLimitsModeAndPrivateVersionedKeyAreMandatory(){for(String key:List.of("attempt-limit","retry-limit","rate-count","rate-seconds","disclosure-limit","retention-seconds")){var e=env();e.setProperty("cinenest.access."+key,"0");assertThatThrownBy(()->new AccessPolicy(e).configured()).isInstanceOf(AccessFailure.class);}var e=env();e.setProperty("cinenest.access.mode","PRODUCTION");var wrongMode=new AccessPolicy(e);assertThatThrownBy(wrongMode::configured).isInstanceOf(AccessFailure.class);e=env();e.setProperty("cinenest.access.keys.test-v1","not-a-key");var broken=new AccessPolicy(e);assertThatThrownBy(broken::configured).isInstanceOf(AccessFailure.class);}
}
